import { useState } from 'react'
import { Field } from 'moru-ui'
import { Textarea } from 'moru-ui'

export function Notes() {
  const [notes, setNotes] = useState('')
  return (
    <Field label="Notes">
      <Textarea value={notes} onChange={(event) => setNotes(event.target.value)} rows={4} />
    </Field>
  )
}

